    Клиент = Справочники.Клиенты.СоздатьЭлемент();
    Клиент.Наименование = "Учебный P5 — новая работа"; Клиент.Записать();
    Услуга = Справочники.Услуги.СоздатьЭлемент();
    Услуга.Наименование = "Учебная P5 — новая работа"; Услуга.Записать();
    Документ = Документы.ЗаявкаУслуги.СоздатьДокумент();
    Документ.Дата = Дата(2026,11,8,12,0,0);
    Документ.Клиент = Клиент.Ссылка; Документ.Услуга = Услуга.Ссылка;
    Документ.Статус = Перечисления.СтатусыЗаявки.Новая;

    Документ.ДлительностьМинут = -1;
    МинусОтклонен = Ложь;
    Попытка Документ.Записать();
    Исключение МинусОтклонен = Документ.Ссылка.Пустая(); КонецПопытки;
    Документ.ДлительностьМинут = 0; Документ.Записать();
    СсылкаДо = Документ.Ссылка;
    НольСохранен = СсылкаДо.ПолучитьОбъект().ДлительностьМинут = 0;
    Документ.ДлительностьМинут = 1440; Документ.Записать();
    ВерхСохранен = СсылкаДо.ПолучитьОбъект().ДлительностьМинут = 1440;
    Документ.ДлительностьМинут = 1441;
    ОтказПолучен = Ложь;
    Попытка Документ.Записать();
    Исключение ОтказПолучен = Истина; КонецПопытки;
    Факт = СсылкаДо.ПолучитьОбъект();
    ОтказСохранилБазу = ОтказПолучен И Факт.Ссылка = СсылкаДо И Факт.ДлительностьМинут = 1440;
    Возврат Новый Структура("МинусОтклонен,НольСохранен,ВерхСохранен,ОтказСохранилБазу",
        МинусОтклонен,НольСохранен,ВерхСохранен,ОтказСохранилБазу);
КонецФункции

